{"query": "
-- Check average actors per film (joining film_actor causes row multiplication)
SELECT AVG(actor_count) as avg_actors_per_film, MAX(actor_count) as max_actors_per_film
FROM (
    SELECT film_id, COUNT(*) as actor_count 
    FROM film_actor 
    GROUP BY film_id
) t;
"}

{"query": "
-- Check if film_category is also 1:1 with film or 1:many
SELECT COUNT(*) as total_film_category, COUNT(DISTINCT film_id) as unique_films
FROM film_category;
"}
